246	    @Override
247	    @Transactional
248	    public void saveOwner(Owner owner) throws DataAccessException {
249	        if (owner.getMemberId() == null) {
250	            owner.setMemberId(generateMemberId(owner));
251	        }
252	        ownerRepository.save(owner);
253	
254	    }
255	
256	    /** Fixed city-to-region table used to derive an owner's region for its member id. */
257	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
258	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
259	
260	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
261	     *  when deriving an owner's region. */
262	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
263	        "NSW", new int[] {2000, 2099},
264	        "VIC", new int[] {3000, 3099},
265	        "QLD", new int[] {4000, 4099});
266	
267	    /**
268	     * Builds an owner's unified member id formatted {@code '<REGION><FY><HASH8><CHK>'}, where REGION
269	     * is the region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}), FY is
270	     * the two-digit fiscal year of the owner's business-day-adjusted registration date, HASH8 is the
271	     * first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized telephone
272	     * concatenated with its last name, and CHK is a single Luhn check digit computed over the digits
273	     * of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW271A2B3C4D5'}).
274	     *
275	     * <p>When the computed member id collides with an existing owner's {@code memberId}, {@code '-<n>'}
276	     * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
277	     * always receive distinct member ids.
278	     */
279	    private String generateMemberId(Owner owner) {
280	        String region = deriveRegion(owner);
281	        String fy = String.format("%02d", Owner.fiscalYear(owner.resolveRegistrationDate()) % 100);
282	        String core = region + fy + hash8(owner);
283	        String base = core + luhnCheckDigit(core);
284	        Set<String> existing = ownerRepository.findAll().stream()
285	            .map(Owner::getMemberId)
286	            .filter(Objects::nonNull)
287	            .collect(Collectors.toSet());
288	        if (!existing.contains(base)) {
289	            return base;
290	        }
291	        for (int n = 2; ; n++) {
292	            String candidate = base + "-" + n;
293	            if (!existing.contains(candidate)) {
294	                return candidate;
295	            }
296	        }
297	    }
298	
299	    /**
300	     * Computes the Luhn check digit (0-9) over the decimal digits contained in {@code value},
301	     * ignoring any non-digit characters. Used to derive the CHK segment of an owner's member id.
302	     */
303	    private static int luhnCheckDigit(String value) {
304	        int sum = 0;
305	        boolean dbl = true;
306	        for (int i = value.length() - 1; i >= 0; i--) {
307	            char c = value.charAt(i);
308	            if (c < '0' || c > '9') {
309	                continue;
310	            }
311	            int d = c - '0';
312	            if (dbl) {
313	                d *= 2;
314	                if (d > 9) {
315	                    d -= 9;
316	                }
317	            }
318	            sum += d;
319	            dbl = !dbl;
320	        }
321	        return (10 - (sum % 10)) % 10;
322	    }
323	
324	    /**
325	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
326	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
327	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
328	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
329	     * city is not in the table.
330	     */
331	    private static String deriveRegion(Owner owner) {
332	        String postcode = owner.getPostcode();
333	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
334	            int value = Integer.parseInt(postcode);
335	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
336	                int[] range = entry.getValue();
337	                if (value >= range[0] && value <= range[1]) {
338	                    return entry.getKey();
339	                }
340	            }
341	        }
342	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
343	    }
344	
345	    /**
346	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
347	     * digest over its normalized telephone concatenated with its last name.
348	     */
349	    private static String hash8(Owner owner) {
350	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
351	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
352	        return HashUtils.sha256UpperHex(telephone + lastName, 8);
353	    }
354	
355	    /**
356	     * Whether any existing owner has the given derived identity key. This is the single basis for
357	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
358	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
359	     */
360	    @Override
361	    @Transactional(readOnly = true)
362	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
363	        if (identityKey == null) {
364	            return false;
365	        }
366	        return ownerRepository.findAll().stream()
367	            .filter(existing -> !existing.isDeleted())
368	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
369	    }
370	
371	    /**
372	     * Finds the id of an existing owner that {@code owner} soft-matches (a possible duplicate): one
373	     * whose surname shares this owner's {@code soundex(lastName)} and whose postcode matches, yet
374	     * whose identity key differs (so it is not itself a hard duplicate). This is a weaker match than
375	     * the hard-duplicate identity key, so it is only meaningful for an owner that is not itself a hard
376	     * duplicate; in particular two owners with the same lastName and postcode but different telephones
377	     * are soft matches rather than hard duplicates. When several owners match, the one with the lowest
378	     * id is returned; {@code null} is returned when there is no match (or lastName/postcode is absent),
379	     * meaning the owner is not a possible duplicate.
380	     */
381	    @Override
382	    @Transactional(readOnly = true)
383	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
384	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
385	            return null;
386	        }
387	        String soundex = Owner.soundex(owner.getLastName());
388	        String postcode = owner.getPostcode();
389	        String identityKey = owner.getIdentityKey();
390	        return ownerRepository.findAll().stream()
391	            .filter(existing -> !existing.isDeleted())
392	            .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName()))
393	                && postcode.equals(existing.getPostcode())
394	                && !Objects.equals(identityKey, existing.getIdentityKey()))
395	            .map(Owner::getId)
396	            .filter(Objects::nonNull)
397	            .min(Comparator.naturalOrder())
398	            .orElse(null);
399	    }
400	
401	    /**
402	     * Counts the existing owners whose firstName and lastName match the given values
403	     * case-insensitively. Used to record an owner's namesake count at creation time.
404	     */
405	    @Override
406	    @Transactional(readOnly = true)
407	    public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
408	        if (firstName == null || lastName == null) {
409	            return 0;
410	        }
411	        return (int) ownerRepository.findAll().stream()
412	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
413	                && lastName.equalsIgnoreCase(existing.getLastName()))
414	            .count();
415	    }
416	
417	    /**
418	     * Counts the existing owners whose city matches the given value case-insensitively.
419	     * Used to enforce the per-city capacity rule at creation time.
420	     */
421	    @Override
422	    @Transactional(readOnly = true)
423	    public int countOwnersByCity(String city) throws DataAccessException {
424	        if (city == null) {
425	            return 0;
426	        }
427	        return (int) ownerRepository.findAll().stream()
428	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
429	            .count();
430	    }
431	
432	    /**
433	     * Counts the existing owners whose registration date matches the given value.
434	     * Used to enforce the per-day owner creation limit.
435	     */
436	    @Override
437	    @Transactional(readOnly = true)
438	    public int countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
439	        if (registrationDate == null) {
440	            return 0;
441	        }
442	        return (int) ownerRepository.findAll().stream()
443	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
444	            .count();
445	    }
446	
447	    /**
448	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
449	     * SHA-256 digest over the owner's normalized last name, a {@code '|'} separator and its postcode
450	     * ({@code normalizedLastName + '|' + postcode}). Owners that share a last name and postcode
451	     * therefore map to the same household id automatically, without any explicit linking. Returns
452	     * {@code null} when the last name or postcode is absent or blank, since no household can be
453	     * formed without both.
454	     */
455	    @Override
456	    @Transactional(readOnly = true)
457	    public String computeHouseholdId(Owner owner) throws DataAccessException {
458	        if (owner == null) {
459	            return null;
460	        }
461	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
462	        String postcode = owner.getPostcode();
463	        if (normalizedLastName == null || normalizedLastName.isBlank()
464	            || postcode == null || postcode.isBlank()) {
465	            return null;
466	        }
467	        return HashUtils.sha256UpperHex(normalizedLastName + "|" + postcode, 12);
468	    }
469	
470	    /**
471	     * Counts the owners that belong to the household identified by the given (deterministic)
472	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
473	     * the membership-points calculation. Returns {@code 0} when the id is absent.
474	     */
475	    @Override
476	    @Transactional(readOnly = true)
477	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
478	        if (householdId == null || householdId.isBlank()) {
479	            return 0;
480	        }
481	        return (int) ownerRepository.findAll().stream()
482	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
483	            .count();
484	    }
485	
486	    /**
487	     * Returns the existing, non-deleted owners that belong to the household identified by the given
488	     * (deterministic) household id, i.e. the current members of that household. Used to derive the
489	     * membership-level ceiling a new owner joining the household is subject to. Returns an empty
490	     * collection when the id is absent.
491	     */
492	    @Override
493	    @Transactional(readOnly = true)
494	    public Collection<Owner> findOwnersByHouseholdId(String householdId) throws DataAccessException {
495	        if (householdId == null || householdId.isBlank()) {
496	            return List.of();
497	        }
498	        return ownerRepository.findAll().stream()
499	            .filter(existing -> !existing.isDeleted())
500	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
501	            .toList();
502	    }
503	
504	    /**
505	     * Computes the membership-level ceiling for a new owner joining the household identified by the
506	     * given (deterministic) household id: one above the current maximum membershipLevel among the
507	     * existing (non-deleted) household members. The members' live household size is passed explicitly
508	     * to {@link Owner#membershipLevel(Integer)}, so no persistent state is mutated. Returns
509	     * {@code null} when the household has no existing member, so no cap applies to the new owner.
510	     */
511	    @Override
512	    @Transactional(readOnly = true)
513	    public Integer computeMembershipLevelCap(String householdId) throws DataAccessException {
514	        Collection<Owner> members = findOwnersByHouseholdId(householdId);
515	        if (members.isEmpty()) {
516	            return null;
517	        }
518	        int maxLevel = 0;
519	        for (Owner member : members) {
520	            int level = member.membershipLevel(members.size());
521	            if (level > maxLevel) {
522	                maxLevel = level;
523	            }
524	        }
525	        return maxLevel + 1;
526	    }
527	
528	    /**
529	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
530	     * runs of whitespace to a single space and lower-casing, so values that differ only in
531	     * whitespace or letter case are treated as equal.
532	     */
533	    private static String normalizeHouseholdField(String value) {
534	        if (value == null) {
535	            return null;
536	        }
537	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
538	    }
539	
540	    @Override
541	    @Transactional(readOnly = true)
542	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
543	        return ownerRepository.findByLastName(lastName);
544	    }
545	
546	    /**
547	     * Returns the id of the owner previously created for the given idempotency key, or {@code null}
548	     * when the key has not been seen (or is absent), meaning the create should proceed normally.
549	     */
550	    @Override
551	    public Integer findOwnerIdByIdempotencyKey(String idempotencyKey) throws DataAccessException {
552	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
553	            return null;
554	        }
555	        return idempotencyKeys.get(idempotencyKey);
556	    }
557	
558	    /**
559	     * Records that the given idempotency key produced the owner with the given id, so a later create
560	     * repeating the key replays that owner instead of duplicating it. No-op when the key is absent.
561	     */
562	    @Override
563	    public void registerIdempotencyKey(String idempotencyKey, Integer ownerId) throws DataAccessException {
564	        if (idempotencyKey == null || idempotencyKey.isBlank() || ownerId == null) {
565	            return;
566	        }
567	        idempotencyKeys.put(idempotencyKey, ownerId);
568	    }
569	
570	    @Override
571	    @Transactional(readOnly = true)
572	    public Collection<Visit> findVisitsByPetId(int petId) {
573	        return visitRepository.findByPetId(petId);
574	    }
575	
576	    @Override
577	    @Transactional(readOnly = true)
578	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
579	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
580	    }
581	
582	    private <T> T findEntityById(Supplier<T> supplier) {
583	        try {
584	            return supplier.get();
585	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
586	            // Just ignore not found exceptions for Jdbc/Jpa realization
587	            return null;
588	        }
589	    }
590	
591	}
