270	     * Whether this owner was flagged a possible (soft-match) duplicate at creation: it was not a
271	     * hard duplicate, yet it shared an existing owner's lastName and postcode while carrying a
272	     * different telephone. False when no such match existed.
273	     */
274	    public Boolean getPossibleDuplicate() {
275	        return this.possibleDuplicate;
276	    }
